import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { renderSkillMemorySection } from "../../packages/core/src/lobu-guidance.ts";

const SKILL_PATH = resolve(process.cwd(), "skills/lobu/SKILL.md");
const START_MARKER = "<!-- lobu-memory-guidance:start -->";
const END_MARKER = "<!-- lobu-memory-guidance:end -->";

const skill = readFileSync(SKILL_PATH, "utf-8");
const startIndex = skill.indexOf(START_MARKER);
const endIndex = skill.indexOf(END_MARKER);

if (startIndex === -1 || endIndex === -1 || endIndex < startIndex) {
	throw new Error(`Could not find guidance markers in ${SKILL_PATH}`);
}

const generated = renderSkillMemorySection();
const replacement = `${START_MARKER}\n${generated}\n${END_MARKER}`;
const next = `${skill.slice(0, startIndex)}${replacement}${skill.slice(endIndex + END_MARKER.length)}`;

writeFileSync(SKILL_PATH, next);
console.log(`Synced ${SKILL_PATH}`);
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { LOBU_SKILL_MARKDOWN } from "../lobu-skill.generated";

// The `skill://lobu` MCP resource serves the bundled Lobu SKILL.md so Slackbot
// (and any MCP client) can read it as reference material. The content is
// embedded at build time (see scripts/gen-skill-resource.ts) so it ships
// identically in prod and local dev. Guard against the generated constant
// drifting from the source file.
const skillPath = resolve(__dirname, "../../../../../skills/lobu/SKILL.md");

describe("lobu skill resource", () => {
  it("stays in sync with skills/lobu/SKILL.md", () => {
    const source = readFileSync(skillPath, "utf-8");
    expect(LOBU_SKILL_MARKDOWN).toBe(source);
  });

  it("is non-empty and carries the skill frontmatter", () => {
    expect(LOBU_SKILL_MARKDOWN.length).toBeGreaterThan(0);
    expect(LOBU_SKILL_MARKDOWN).toContain("name: lobu");
  });
});
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import {
	renderFallbackSystemContext,
	renderSkillMemorySection,
} from "@lobu/core";
import { describe, expect, it } from "vitest";

// Memory guidance now lives in the bundled Lobu skill. Resolve relative to this
// file so the test works regardless of `process.cwd()` (worktrees, vitest's
// per-package cwd, IDE runners).
const skillPath = resolve(__dirname, "../../../../../skills/lobu/SKILL.md");
const START_MARKER = "<!-- lobu-memory-guidance:start -->";
const END_MARKER = "<!-- lobu-memory-guidance:end -->";

describe("lobu guidance sync", () => {
	it("renders plugin fallback context with namespaced tool names", () => {
		const text = renderFallbackSystemContext();

		expect(text).toContain("lobu_save_memory");
		expect(text).toContain("lobu_search_memory");
		expect(text).toContain("<lobu-system>");
	});

	it("keeps the skill memory section in sync with the shared renderer", () => {
		const skill = readFileSync(skillPath, "utf-8");
		const start = skill.indexOf(START_MARKER);
		const end = skill.indexOf(END_MARKER);

		expect(start).toBeGreaterThanOrEqual(0);
		expect(end).toBeGreaterThan(start);

		const generatedSection = skill
			.slice(start + START_MARKER.length, end)
			.trim();

		expect(generatedSection).toBe(renderSkillMemorySection());
	});
});

